public class Product
{
    public string Name;
    public decimal Price;

    public Product(string name, decimal price)
    {
        Name = name;
        Price = price;
    }
}

var p = new Product("Widget", 9.99m);
Console.WriteLine($"{p.Name} - {p.Price:C}");

questions.explanation:
The default constructor sets name to "Alice". The parameterized constructor uses 'this(name, age)' to chain to another constructor that sets name to "Charlie". The last assignment in the chain wins: "Charlie".

public class Person { string name = "Alice"; public Person() {} public Person(string name) { this.name = name; Console.WriteLine(this.name); } public Person(string name, int age) : this(name) { name = "Bob"; } }
var p = new Person("Charlie");

